static void check(bool ok,const char* expr,unsigned line){++assertions;if(!ok){std::fprintf(stderr,"FAIL line=%u condition=%s\n",line,expr);throw std::runtime_error("assertion failure");}}
#define CHECK(x) check(bool(x),#x,__LINE__)
static void tick(Driver& d,uint32_t now=0){auto attempts=d.attempts(),ack=d.acknowledgements();d.step(now);CHECK(d.attempts()-attempts<=1);CHECK(d.work().reportAttempts+d.work().runtimeTicks<=1);if(d.attempts()!=attempts)CHECK(d.acknowledgements()==ack);}
static void compile(Driver& d,const char* text="STRING a"){CHECK(d.compileMemory(text,std::strlen(text)));unsigned n=0;while(d.compiler().state()==p::CompileState::Compiling&&n++<p::MaxCompileSteps)d.compileStep();CHECK(n<=p::MaxCompileSteps);CHECK(d.program().ready());}
static void prepared(Driver& d,const char* text="STRING a",uint32_t now=0){compile(d,text);CHECK(d.begin(now));unsigned n=0;while(d.state()==State::Syncing&&n++<12)tick(d,now);CHECK(d.state()==State::Prepared);}
static void running(Driver& d,const char* text="STRING a"){prepared(d,text);CHECK(d.start());}
static void intent(Driver& d){unsigned n=0;while(d.bridge().intent()!=b::Intent::Waiting&&d.state()==State::Running&&n++<100)tick(d);CHECK(d.bridge().intent()==b::Intent::Waiting);}
static void pending(Driver& d){intent(d);d.transport().defaultPlan({Outcome::Submitted,false,false});tick(d);CHECK(d.transport().unresolved());}
static void finish(Driver& d,uint32_t now=0){unsigned n=0;while(d.state()==State::Running&&n++<2000)tick(d,now);CHECK(n<=2000&&d.state()==State::TerminalUndrained);}
static void done(Driver& d){CHECK(d.transport().publish(d.transport().notice(NoticeKind::Success)));CHECK(d.transport().publish(d.transport().notice(NoticeKind::Retired)));}
static void drain(Driver& d){d.transport().defaultPlan({});CHECK(d.drain());unsigned n=0;while(d.state()==State::DrainPending&&n++<12)tick(d);CHECK(d.state()==State::Drained);CHECK(d.record(d.recordCount()-1)->intent==0);}
static void wire(const Transfer* t,const unsigned char (&bytes)[9]){CHECK(t&&t->wire.length==9);CHECK(!std::memcmp(t->wire.bytes,bytes,9));}
